export interface Student {
  id: string;
  name: string;
  classId: string;
  feeStatus: "paid" | "due";
}

const students: Student[] = [];

/** Look up one student by id. Returns null when not found. */
export function findStudentById(id: string): Student | null {
  return students.find(s => s.id === id) ?? null;
}

export function allStudentsInClass(classId: string): Student[] {
  return students.filter(s => s.classId === classId);
}


// ── src/models/parent.ts ─────────────────────────── 22 lines
export interface Parent {
  id: string;
  name: string;
  email: string;
  linkedStudentIds: string[];
}

const parents: Parent[] = [];

export function findParentById(id: string): Parent | null {
  return parents.find(p => p.id === id) ?? null;
}

export async function saveParent(parent: Parent): Promise<void> {
  const i = parents.findIndex(p => p.id === parent.id);
  if (i >= 0) parents[i] = parent;
}


