// src/chunk/naive.ts
export function naiveChunk(text: string, file: string) {
  const SIZE = 400, OVERLAP = 60;      // 1000/150 on a real repo
  const chunks = [];

  for (let i = 0; i < text.length; i += SIZE - OVERLAP) {
    const slice = text.slice(i, i + SIZE);
    chunks.push({
      id: file + ":" + i,
      text: slice,
      file,
      startLine: lineAt(text, i),
      endLine: lineAt(text, i + slice.length)
    });
  }
  return chunks;
}

function lineAt(text: string, i: number) {
  return text.slice(0, i).split("\n").length;
}


