function rrf(lists: Chunk[][], k = 60) {
  const scores = new Map<string, number>();
  for (const list of lists) {
    list.forEach((c, rank) => {
      scores.set(c.id, (scores.get(c.id) ?? 0) + 1 / (k + rank + 1));
    });
  }
  return [...scores.entries()]
    .sort((a, b) => b[1] - a[1])
    .map(([id]) => byId.get(id));
}

