// src/chunk/heading.ts  — the entire new chunker

export function headingChunk(md: string, file: string) {
  const lines = md.split("\n");
  const trail: string[] = [];
  const chunks = [];
  let buf: string[] = [], start = 1;

  lines.forEach((line, i) => {
    const h = line.match(/^(#{1,6})\s+(.*)/);
    if (h) {
      flush(i);
      const level = h[1].length;
      trail.length = level - 1;
      trail[level - 1] = h[2];
      start = i + 1;
    } else buf.push(line);
  });
  flush(lines.length);

  function flush(end: number) {
    const text = buf.join("\n").trim();
    buf = [];
    if (text.length < 200) return;              // merge crumbs
    chunks.push({
      text, file, startLine: start, endLine: end,
      headingTrail: trail.filter(Boolean).join(" > "),
      embedText: trail.filter(Boolean).join(" > ") + "\n\n" + text
    });
  }
  return chunks;
}

